import base64,pathlib,json
B=pathlib.Path(__file__).resolve().parent.parent
R=B/'v3'
def b64(n): return 'data:image/jpeg;base64,'+base64.b64encode((R/'img'/n).read_bytes()).decode()
fonts=(R/'fonts/home.css').read_text()
jobs=[('Bathroom','Interior','bath'),('Exterior repaint','Gilbert','home'),('Cabinet refinish','Queen Creek','kitchen'),('Front door stain','Wood refinish','door'),('Garage doors','Exterior','gdoor')]
J=json.dumps([{'t':t,'p':p,'a':b64(k+'-after-sm.jpg'),'b':b64(k+'-before-sm.jpg')} for t,p,k in jobs])
svc=[('#1f3563','Exterior painting','Stucco, trim and garage doors with crisp lines and clean finishes.'),('#b7ab98','Interior painting','Walls, ceilings, doors and trim, from soft neutrals to bold color.'),('#54535a','Cabinet refinishing','A new kitchen look without the remodel.'),('#5b3720','Doors and wood stain','Weathered wood brought back to a rich, even color.'),('#46594f','Commercial repaints','Restaurants, warehouses and shops, planned around your space.'),('#b01f2a','Accent walls and details','Stripes and color blocks, taped and cut sharp.')]
chips=''.join(f'<li class="chip"><i style="background:{c}"></i><div><h3>{t}</h3><p>{d}</p><small>{c.upper()}</small></div></li>' for c,t,d in svc)
faq=[('Do you paint homes and businesses?','Both. We paint houses, restaurants, warehouses and shops, inside and out.'),('What can you paint?','Exteriors, interiors, kitchen cabinets, doors and wood stain, accent walls, and commercial repaints.'),('Who will I deal with?','The business is owner-operated by Jonathan Bernal, so you talk with the owner.'),('How much does it cost?','Every job is different, so we give a free estimate. Call, text or send the short form.')]
faqh=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faq)
std=[('Prep first','Surfaces are cleaned, patched and protected before paint goes on.'),('Your space, protected','Floors, furniture and fixtures are covered and the job stays tidy.'),('Straight answers','You talk to the owner from the free estimate to the last coat.'),('Done right','Quality, precision and perfection on every wall.')]
stdh=''.join(f'<li><span>{i+1:02d}</span><h3>{t}</h3><p>{d}</p></li>' for i,(t,d) in enumerate(std))
ic={'call':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2z"/></svg>','sms':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 5h16v11H9l-5 4z"/></svg>','est':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/></svg>'}
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>JB'S Pro Painters LLC | Painters in Gilbert, Mesa and the East Valley, AZ</title>
<meta name="description" content="Owner-operated interior and exterior painters in Gilbert, Mesa, Chandler, Tempe, Scottsdale and Queen Creek, AZ. Licensed and insured. Free estimates.">
<meta property="og:title" content="JB'S Pro Painters LLC"><meta property="og:description" content="Owner-operated painters across the East Valley. Free estimates."><meta property="og:image" content="og.jpg">
<style>{fonts}
:root{{--bg:#050a1c;--bg2:#0a1433;--bg3:#0e1b46;--ink:#e8ecf7;--mute:#a9b5d2;--line:#ffffff26;--blue:#2459e6;--blue2:#7da3ff;--silver:#d5dcea;--paper:#eef2fa;--pink:#0a1433}}
*{{box-sizing:border-box;margin:0}}html{{overflow-x:clip;scroll-behavior:smooth;scroll-padding-top:76px}}
body{{background:var(--bg);color:var(--ink);font:400 18px/1.65 'Onest',system-ui,sans-serif;overflow-x:clip;padding-bottom:84px;-webkit-font-smoothing:antialiased}}
img{{display:block;max-width:100%}}a{{color:inherit}}:focus-visible{{outline:3px solid var(--blue2);outline-offset:3px}}
h1,h2,h3{{font-family:'Gilda Display',Georgia,serif;font-weight:400;line-height:1.06;text-wrap:balance}}
.w{{width:min(1240px,100% - 40px);margin-inline:auto}}
.btn{{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:54px;padding:0 28px;border-radius:99px;background:var(--blue);color:#fff;font-weight:650;font-size:17px;text-decoration:none;border:1.5px solid var(--blue);cursor:pointer;transition:background .2s,transform .2s}}.btn:hover{{background:#1c47c0;transform:translateY(-2px)}}.btn svg{{width:20px;height:20px}}
.btn--g{{background:none;border-color:#ffffff66;color:#fff}}.btn--g:hover{{background:#fff;color:var(--bg2)}}
header{{position:sticky;top:0;z-index:50;background:#050a1cf2;backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}}header .w{{display:flex;align-items:center;justify-content:space-between;height:68px}}
.brand{{display:flex;align-items:center;gap:12px;text-decoration:none;font-weight:700;letter-spacing:.14em;font-size:14px}}.brand img{{border-radius:10px}}
header .btn{{min-height:44px;padding:0 20px;font-size:15px}}.hn{{display:inline}}@media(max-width:600px){{.hn,.brand span{{display:none}}}}
.hero{{padding:clamp(36px,6vw,84px) 0 clamp(48px,6vw,80px)}}.hero .w{{display:grid;grid-template-columns:1fr 1.05fr;gap:clamp(28px,5vw,72px);align-items:center}}
.eyebrow{{font:600 13px 'Onest';letter-spacing:.16em;text-transform:uppercase;color:var(--blue2);margin-bottom:18px}}
.hero h1{{font-size:clamp(44px,6.2vw,88px);letter-spacing:-.015em}}.hero h1 em{{font-style:normal;color:var(--blue2)}}
.lead{{margin-top:22px;font-size:clamp(18px,1.6vw,21px);color:#dbe2f3;max-width:34ch}}.cta{{display:flex;flex-wrap:wrap;gap:12px;margin-top:30px}}
.trust{{display:flex;flex-wrap:wrap;gap:10px 22px;margin-top:30px;padding-top:22px;border-top:1px solid var(--line);color:var(--mute);font-size:15px;font-weight:550}}.trust span{{display:flex;align-items:center;gap:8px}}.trust span::before{{content:"";width:8px;height:8px;background:var(--blue2);border-radius:2px}}
.stage{{position:relative;display:block;width:100%;aspect-ratio:4/5;max-height:72svh;border:0;padding:0;border-radius:22px;overflow:hidden;cursor:pointer;background:var(--bg3);box-shadow:0 0 0 1px #ffffff2e,0 40px 80px -40px #000}}
.stage img{{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:opacity .5s}}.stage .b{{opacity:0}}.stage[data-b=true] .b{{opacity:1}}.stage[data-b=true] .a{{opacity:0}}
.tag{{position:absolute;left:14px;top:14px;background:#050a1ce6;border:1px solid var(--line);border-radius:12px;padding:9px 14px;text-align:left;display:grid;color:#fff}}.tag b{{font:700 17px 'Onest'}}.tag small{{font-size:13px;color:#cfd8ee}}
.hint{{position:absolute;left:50%;bottom:14px;transform:translateX(-50%);display:flex;align-items:center;gap:10px;min-height:44px;padding:0 20px;border-radius:99px;background:#050a1cf5;border:1px solid #ffffff40;color:#fff;font:600 15px 'Onest';white-space:nowrap}}.hint i{{width:9px;height:9px;border-radius:50%;background:var(--blue2);animation:pu 1.8s infinite}}@keyframes pu{{0%{{box-shadow:0 0 0 0 #7da3ffaa}}100%{{box-shadow:0 0 0 12px #7da3ff00}}}}
.thumbs{{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-top:10px}}.thumbs button{{position:relative;aspect-ratio:1;border:0;padding:0;border-radius:12px;overflow:hidden;cursor:pointer;opacity:.6;transition:opacity .2s}}.thumbs button[aria-selected=true]{{opacity:1;box-shadow:0 0 0 2px var(--blue2)}}.thumbs img{{width:100%;height:100%;object-fit:cover}}
.sec{{padding:clamp(72px,9vw,128px) 0}}.sec h2{{font-size:clamp(34px,5vw,68px);max-width:16ch}}.sec .sub{{margin-top:16px;color:var(--mute);max-width:46ch;font-size:19px}}
.paper{{background:var(--paper);color:#0a1433}}.paper .sub{{color:#4a5878}}.paper .eyebrow{{color:#1c47c0}}
.chips{{list-style:none;padding:0;margin:44px 0 0;display:grid;grid-template-columns:repeat(3,1fr);gap:18px}}
.chip{{display:grid;grid-template-rows:96px 1fr;background:#fff;border-radius:14px;overflow:hidden;box-shadow:0 1px 0 #c9d3e8,0 18px 36px -24px #0a143360;transition:transform .3s}}.chip:hover{{transform:translateY(-6px)}}.chip i{{display:block}}.chip div{{padding:18px 20px 20px}}.chip h3{{font-size:24px}}.chip p{{margin-top:8px;font-size:16px;line-height:1.55;color:#4a5878}}.chip small{{display:block;margin-top:14px;font:600 12px 'Onest';letter-spacing:.14em;color:#6b7aa0}}
.two{{display:grid;grid-template-columns:.85fr 1.15fr;gap:clamp(32px,6vw,90px);align-items:start}}
.own{{position:relative;border-radius:22px;overflow:hidden;aspect-ratio:1/1.05;background:var(--bg3);box-shadow:0 0 0 1px #ffffff26}}.own img{{width:100%;height:100%;object-fit:cover;object-position:22% 40%}}.own div{{position:absolute;left:12px;right:12px;bottom:12px;background:#050a1cf0;border-radius:12px;padding:10px 14px;display:grid;font-size:14px;color:#cfd8ee}}.own b{{font:700 18px 'Onest';color:#fff}}
blockquote{{margin-top:22px;padding-left:18px;border-left:2px solid var(--blue2);font:400 clamp(20px,2vw,26px)/1.35 'Gilda Display',serif;color:#f2f5fc}}blockquote small{{display:block;margin-top:8px;font:500 14px 'Onest';color:var(--mute)}}
.std{{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:1fr 1fr;gap:0 34px}}.std li{{padding:24px 0;border-top:1px solid var(--line)}}.std span{{font:600 13px 'Onest';letter-spacing:.14em;color:var(--blue2)}}.std h3{{font-size:26px;margin:8px 0 6px}}.std p{{color:var(--mute);font-size:17px;line-height:1.6}}
.steps{{list-style:none;padding:0;margin:44px 0 0;display:grid;grid-template-columns:repeat(3,1fr);gap:0}}.steps li{{padding:8px 34px 8px 0;margin-right:34px;border-right:1px solid var(--line)}}.steps li:last-child{{border:0;margin:0}}.steps b{{display:inline-grid;place-items:center;width:44px;height:44px;border-radius:50%;background:var(--blue);font:700 18px 'Onest';color:#fff}}.steps h3{{font-size:28px;margin:16px 0 8px}}.steps p{{color:var(--mute)}}
.areas{{display:flex;flex-wrap:wrap;gap:10px;margin-top:26px}}.areas span{{padding:10px 18px;border:1px solid #ffffff40;border-radius:99px;font-weight:550}}
details{{border-top:1px solid var(--line)}}details:last-child{{border-bottom:1px solid var(--line)}}summary{{list-style:none;display:flex;justify-content:space-between;align-items:center;gap:16px;min-height:64px;cursor:pointer;font:600 19px 'Onest'}}summary::-webkit-details-marker{{display:none}}summary::after{{content:"+";font-size:26px;color:var(--blue2);transition:transform .25s}}details[open] summary::after{{transform:rotate(45deg)}}details p{{padding:0 0 22px;color:var(--mute);max-width:58ch}}
.est{{background:var(--blue);color:#fff}}.est .eyebrow{{color:#dce6ff}}.est .sub{{color:#e3ebff}}.est form{{background:var(--bg2);border-radius:20px;padding:clamp(20px,3vw,32px);display:grid;gap:16px}}
label{{display:grid;gap:7px;font:600 13px 'Onest';letter-spacing:.08em;text-transform:uppercase}}input,select{{font:400 17px 'Onest';letter-spacing:0;text-transform:none;min-height:54px;border-radius:12px;border:1px solid #ffffff55;background:var(--bg);color:#fff;padding:0 14px;width:100%}}.hp{{position:absolute;left:-9999px}}form[hidden]{{display:none}}.est .btn{{background:#fff;color:var(--bg2);border-color:#fff}}.est .btn:hover{{background:var(--silver)}}#ok{{min-height:1.4em;font-weight:600;text-transform:none}}
.ph{{display:block;margin-top:24px;font:400 clamp(32px,4.4vw,56px) 'Gilda Display',serif;text-decoration:none}}
footer{{padding:34px 0 40px;color:var(--mute);font-size:14px}}footer .w{{display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px}}footer a{{font-weight:600}}
.bar{{display:none}}
@media(max-width:1000px){{.hero .w,.two{{grid-template-columns:1fr}}.chips{{grid-template-columns:1fr 1fr}}.steps{{grid-template-columns:1fr}}.steps li{{border:0;border-bottom:1px solid var(--line);margin:0;padding:0 0 28px;margin-bottom:28px}}.stage{{aspect-ratio:4/4.4}}}}
@media(max-width:700px){{body{{font-size:17px}}.chips,.std{{grid-template-columns:1fr}}.hero h1{{font-size:clamp(40px,12vw,56px)}}.bar{{display:grid;grid-template-columns:1fr 1fr 1.5fr;gap:6px;position:fixed;z-index:60;left:10px;right:10px;bottom:max(10px,env(safe-area-inset-bottom));background:#050a1cf5;border:1px solid var(--line);border-radius:99px;padding:6px}}.bar a{{display:flex;align-items:center;justify-content:center;gap:8px;min-height:48px;border-radius:99px;font-weight:700;font-size:15px;text-decoration:none}}.bar a:last-child{{background:var(--blue)}}.bar svg{{width:19px;height:19px}}}}
@media(prefers-reduced-motion:reduce){{*{{transition:none!important;animation:none!important;scroll-behavior:auto!important}}}}
</style></head><body>
<form name="quote" data-netlify="true" netlify-honeypot="bot" hidden><input name="form-name"><input name="name"><input name="phone"><input name="job"><input name="bot"></form>
<header><div class="w"><a class="brand" href="#"><img src="{b64('logo-sq.jpg')}" width="44" height="44" alt="JB'S Pro Painters LLC logo"><span>JB'S PRO PAINTERS</span></a><a class="btn" href="tel:+16024730415">{ic['call']}Call<span class="hn">&nbsp;(602) 473-0415</span></a></div></header>
<main>
<section class="hero"><div class="w"><div><p class="eyebrow">Gilbert &middot; Mesa &middot; Chandler &middot; Tempe &middot; Scottsdale &middot; Queen Creek</p><h1>Painters who answer <em>the phone themselves.</em></h1><p class="lead">Interior and exterior painting for homes and businesses across the East Valley, run by the owner.</p>
<div class="cta"><a class="btn" href="#estimate">{ic['est']}Get a free estimate</a><a class="btn btn--g" href="sms:+16024730415">{ic['sms']}Text us</a></div>
<div class="trust"><span>Licensed</span><span>Insured</span><span>Owner-operated</span></div></div>
<div><button class="stage" id="stage" type="button" data-b="false"><img class="a" id="ia" alt=""><img class="b" id="ib" alt=""><span class="tag"><b id="tb">Fresh coat</b><small id="ts"></small></span><span class="hint" aria-hidden="true"><i></i><span id="th">Tap to see before</span></span></button><div class="thumbs" id="thumbs" role="tablist" aria-label="Choose a project"></div></div></div></section>
<section class="sec paper" id="services"><div class="w"><p class="eyebrow">What we paint</p><h2>Pick a finish. We handle the rest.</h2><p class="sub">Homes and businesses, inside and out.</p><ul class="chips">{chips}</ul></div></section>
<section class="sec" id="about"><div class="w two"><div><div class="own"><img src="{b64('owner-new.jpg')}" alt="Jonathan Bernal, owner of JB'S Pro Painters LLC" loading="lazy"><div><b>Jonathan Bernal</b>Owner, JB'S Pro Painters LLC</div></div></div>
<div><p class="eyebrow">Why JB'S</p><h2>The details we take care of.</h2><p class="sub">Customer satisfaction is the whole job.</p><ul class="std" style="margin-top:30px">{stdh}</ul><blockquote>&ldquo;JB&rsquo;S Pro Painters LLC did an outstanding job painting the exterior…&rdquo;<small>Kenneth R., Facebook review (excerpt)</small></blockquote></div></div></section>
<section class="sec" style="background:var(--bg2)"><div class="w"><p class="eyebrow">How it works</p><h2>Three steps to a finished wall.</h2><ol class="steps"><li><b>1</b><h3>Tell us about the job</h3><p>Send the short form, or just call or text Jonathan.</p></li><li><b>2</b><h3>Get your free estimate</h3><p>Jonathan looks at what you need and gets back to you.</p></li><li><b>3</b><h3>We paint, you enjoy it</h3><p>Prep, protect and paint, inside or out, home or business.</p></li></ol></div></section>
<section class="sec" id="faq"><div class="w two"><div><p class="eyebrow">Service area</p><h2>Serving the East Valley.</h2><div class="areas"><span>Gilbert</span><span>Mesa</span><span>Chandler</span><span>Tempe</span><span>Scottsdale</span><span>Queen Creek</span></div></div><div>{faqh}</div></div></section>
<section class="sec est" id="estimate"><div class="w two"><div><p class="eyebrow">Free estimate</p><h2>Tell us about your project.</h2><p class="sub">Name, phone and the type of job is all we need. Jonathan will get back to you.</p><a class="ph" href="tel:+16024730415">(602) 473-0415</a></div>
<form id="f" name="quote" method="POST" data-netlify="true" netlify-honeypot="bot"><input type="hidden" name="form-name" value="quote"><label class="hp">Leave empty<input name="bot" tabindex="-1" autocomplete="off"></label><label>Name<input name="name" required autocomplete="name"></label><label>Phone<input name="phone" type="tel" required autocomplete="tel"></label><label>Type of job<select name="job"><option>Interior painting</option><option>Exterior painting</option><option>Cabinet refinishing</option><option>Doors and trim</option><option>Commercial</option><option>Not sure yet</option></select></label><button class="btn" type="submit">Request my free estimate</button><p id="ok" role="status"></p></form></div></section>
</main>
<footer><div class="w"><span>&copy; JB'S Pro Painters LLC &middot; jbspropainters@gmail.com</span><a href="https://www.facebook.com/profile.php?id=61584288311213">Facebook</a></div></footer>
<nav class="bar" aria-label="Quick actions"><a href="tel:+16024730415">{ic['call']}Call</a><a href="sms:+16024730415">{ic['sms']}Text</a><a href="#estimate">Free estimate</a></nav>
<script>
const J={J};let cur=0,b=false;const $=id=>document.getElementById(id),st=$('stage');
function show(i,keep){{cur=i;b=false;const j=J[i];$('ia').src=j.a;$('ib').src=j.b;$('ia').alt=j.t+' finished by JB\\'S Pro Painters';$('ib').alt=j.t+' before painting';$('ts').textContent=j.t+' \\u00b7 '+j.p;set(false);document.querySelectorAll('#thumbs button').forEach((x,k)=>x.setAttribute('aria-selected',k===i))}}
function set(v){{b=v;st.dataset.b=v;$('tb').textContent=v?'Before':'Fresh coat';$('th').textContent=v?'Tap to see the finish':'Tap to see before';st.setAttribute('aria-label',J[cur].t+'. Showing '+(v?'before':'the finished job')+'. Tap to switch.')}}
st.addEventListener('click',()=>set(!b));
J.forEach((j,i)=>{{const x=document.createElement('button');x.type='button';x.role='tab';x.setAttribute('aria-label',j.t);x.innerHTML='<img src="'+j.a+'" alt="">';x.onclick=()=>show(i);$('thumbs').appendChild(x)}});show(0);
const f=$('f'),ok=$('ok');f.addEventListener('submit',async e=>{{e.preventDefault();if(f.bot.value)return;const s=f.querySelector('button');s.disabled=true;try{{const r=await fetch('/',{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},body:new URLSearchParams(new FormData(f)).toString()}});if(!r.ok)throw 0;ok.textContent='Thanks! Jonathan will be in touch soon.';f.reset()}}catch(_){{ok.textContent='Could not send. Please call (602) 473-0415.'}}s.disabled=false}});
</script></body></html>'''
out=B/'preview/JBS-new.html';out.write_text(html);print(out.stat().st_size//1024,'KB')
